// Verifica firma HMAC: X-Signature = hex(HMAC-SHA256(secret, X-Timestamp + "." + rawBody)).
// La funzione seguente è copiata identica da agenda-app/n8n/verify-signature.js
// (stesso algoritmo di verifyRequest in agenda-app/src/lib/n8n/sign.ts).
function verifyAgendaSignature(rawBody, secret, timestampMs, signature, nowMs) {
  const crypto = require('crypto');
  const MAX_SKEW_MS = 5 * 60 * 1000;
  if (!Number.isFinite(timestampMs) || Math.abs(nowMs - timestampMs) > MAX_SKEW_MS) return false;
  if (typeof signature !== 'string' || !/^[0-9a-f]{64}$/i.test(signature)) return false;
  const expected = Buffer.from(
    crypto.createHmac('sha256', secret).update(timestampMs + '.' + rawBody).digest('hex'),
    'hex',
  );
  const given = Buffer.from(signature, 'hex');
  if (expected.length !== given.length) return false;
  return crypto.timingSafeEqual(expected, given);
}

const item = $input.first();
const headers = item.json.headers || {};
let rawBody = '';
const bin = item.binary && item.binary.data;
if (bin) {
  try {
    rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  } catch (e) {
    rawBody = Buffer.from(bin.data || '', 'base64').toString('utf8');
  }
}
const tsHeader = String(headers['x-timestamp'] ?? '');
const timestampMs = /^\d{1,16}$/.test(tsHeader) ? Number(tsHeader) : NaN;
const signature = String(headers['x-signature'] ?? '');
const secret = $vars.AGENDA_WEBHOOK_SECRET;
const authorized =
  typeof secret === 'string' &&
  secret.length > 0 &&
  verifyAgendaSignature(rawBody, secret, timestampMs, signature, Date.now());
let body = null;
if (authorized) {
  try {
    body = JSON.parse(rawBody);
  } catch (e) {
    body = null; // firma valida ma JSON non valido: lo rifiuta "Valida input" con 400
  }
}
return [{ json: { authorized, body } }];

const body = $input.first().json.body;
const fail = (message) => [{ json: { ok: false, statusCode: 400, body: { error: 'invalid_input', message } } }];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const normEmail = (e) => (typeof e === 'string' ? e.trim().toLowerCase() : '');
const isDate = (s) => typeof s === 'string' && !Number.isNaN(Date.parse(s));
if (!body || typeof body !== 'object' || Array.isArray(body)) return fail('body mancante o non valido');
const calendarId = $vars.AGENDA_SHARED_CALENDAR_ID;
if (typeof calendarId !== 'string' || calendarId.length === 0) {
  return [{ json: { ok: false, statusCode: 500, body: { error: 'misconfigured' } } }];
}
if (typeof body.requestId !== 'string' || !/^[A-Za-z0-9-]{1,64}$/.test(body.requestId)) return fail('requestId');
const title = typeof body.title === 'string' ? body.title.trim() : '';
if (title.length < 1 || title.length > 200) return fail('title');
if (typeof body.description !== 'string') return fail('description');
if (!isDate(body.start) || !isDate(body.end)) return fail('start/end');
const startMs = Date.parse(body.start);
const endMs = Date.parse(body.end);
if (!(endMs > startMs) || endMs - startMs > 8 * 60 * 60 * 1000) return fail('durata');
const organizerEmail = normEmail(body.organizerEmail);
if (!EMAIL.test(organizerEmail)) return fail('organizerEmail');
if (!Array.isArray(body.attendeeEmails) || body.attendeeEmails.length < 1) return fail('attendeeEmails');
const others = body.attendeeEmails.map(normEmail);
if (others.some((e) => !EMAIL.test(e))) return fail('attendeeEmails');
// Invitati = organizzatore + partecipanti, senza duplicati (max 15 come il freebusy).
const attendees = [...new Set([organizerEmail, ...others])];
if (attendees.length > 15) return fail('attendeeEmails');
if (typeof body.allowConflict !== 'boolean') return fail('allowConflict');
return [{
  json: {
    ok: true,
    calendarId,
    requestId: body.requestId,
    title,
    description: body.description,
    start: new Date(startMs).toISOString(),
    end: new Date(endMs).toISOString(),
    organizerEmail,
    attendees,
    allowConflict: body.allowConflict,
  },
}];

// Idempotenza: se esiste già un evento con questo agendaRequestId lo restituisce.
const calendarError = () => [{ json: { respond: true, statusCode: 502, body: { error: 'calendar_error' } } }];
const res = $input.first().json;
const v = $('Valida input').first().json;
if (res.statusCode !== 200 || !res.body) return calendarError();
const items = Array.isArray(res.body.items) ? res.body.items : [];
const existing = items.find(
  (e) =>
    e &&
    e.status !== 'cancelled' &&
    e.extendedProperties &&
    e.extendedProperties.private &&
    e.extendedProperties.private.agendaRequestId === v.requestId,
);
if (existing) {
  return [{
    json: {
      respond: true,
      statusCode: 200,
      body: { status: 'created', eventId: String(existing.id), htmlLink: String(existing.htmlLink || '') },
    },
  }];
}
return [{ json: { respond: false, emails: v.attendees, timeMin: v.start, timeMax: v.end } }];

// Conflitti sui calendari di organizzatore e partecipanti (il calendario condiviso non conta).
const calendarError = () => [{ json: { respond: true, statusCode: 502, body: { error: 'calendar_error' } } }];
const res = $input.first().json;
const v = $('Valida input').first().json;
if (res.statusCode !== 200 || !res.body || typeof res.body.calendars !== 'object' || res.body.calendars === null) {
  return calendarError();
}
const source = {};
for (const [id, cal] of Object.entries(res.body.calendars)) source[id.toLowerCase()] = cal;
const startMs = Date.parse(v.start);
const endMs = Date.parse(v.end);
const busy = {};
for (const email of v.attendees) {
  const cal = source[email];
  if (!cal || (Array.isArray(cal.errors) && cal.errors.length > 0)) {
    // Errore di lettura = occupato per tutto l'intervallo, mai libero.
    busy[email] = [{ start: v.start, end: v.end }];
    continue;
  }
  const overlapping = (Array.isArray(cal.busy) ? cal.busy : [])
    .filter((b) => Date.parse(b.start) < endMs && Date.parse(b.end) > startMs)
    .map((b) => ({ start: String(b.start), end: String(b.end) }));
  if (overlapping.length > 0) busy[email] = overlapping;
}
if (Object.keys(busy).length > 0 && !v.allowConflict) {
  return [{ json: { respond: true, statusCode: 200, body: { status: 'conflict', busy } } }];
}
const eventBody = {
  summary: v.title,
  description: v.description + '\n\nCreato da ' + v.organizerEmail + ' tramite Agenda aziendale',
  start: { dateTime: v.start, timeZone: 'Europe/Rome' },
  end: { dateTime: v.end, timeZone: 'Europe/Rome' },
  attendees: v.attendees.map((email) => ({ email })),
  extendedProperties: { private: { agendaRequestId: v.requestId } },
};
return [{ json: { respond: false, eventBody } }];

const calendarError = () => [{ json: { respond: true, statusCode: 502, body: { error: 'calendar_error' } } }];
const res = $input.first().json;
if (res.statusCode !== 200 || !res.body || typeof res.body.id !== 'string') return calendarError();
return [{
  json: {
    respond: true,
    statusCode: 200,
    body: { status: 'created', eventId: res.body.id, htmlLink: String(res.body.htmlLink || '') },
  },
}];
